// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface ReadinessOut {
  category: "Clinic" | "IIC" | "IIB" | "IIA" | "I";
  category_label: string;
  edition: string;
  rating_basis: "self-assessment";
  rating_basis_text: string;
  as_of: string;
  date_from: string;
  date_to: string;
  summary: ReadinessSummaryOut;
  score: ScoreSummaryOut;
  areas: ReadinessAreaOut[];
  documents: DocumentCheckOut[];
  indicators: ReadinessIndicatorOut[];
}

export interface ReadinessSummaryOut {
  indicators: number;
  applicable: number;
  ready: number;
  attention: number;
  not_ready: number;
  self_assess: number;
  not_applicable: number;
  /** Haspataal's estimate (ready / applicable), not the PHC's score */
  ready_pct: number | null;
}

/** The establishment's own scores (its latest self-assessments) on the framework's 0-10 scale, not the PHC's verdict. */
export interface ScoreSummaryOut {
  /** Applicable indicators with a score */
  scored: number;
  /** Applicable indicators without one (not zero: not assessed) */
  unscored: number;
  /** The sum of the scores given */
  points: number;
  /** 10 per applicable indicator */
  max_points: number;
  /** Whether the red/yellow minimum scores of this framework were read from its manual */
  thresholds_known: boolean;
  /** Red indicators scored below the red minimum */
  red_below: number[];
  /** Yellow indicators scored below the yellow minimum */
  yellow_below: number[];
}

export interface ReadinessAreaOut {
  area: string;
  name: string;
  indicators: number;
  ready: number;
  attention: number;
  not_ready: number;
  self_assess: number;
  not_applicable: number;
}

export interface DocumentCheckOut {
  key: string;
  title: string;
  state: "Ready" | "Attention" | "NotReady";
  /** One sentence: why it is (not) ready */
  detail: string;
  /** Whether this user may open the document */
  allowed: boolean;
  /** False: the check reads no record (a policy or a register printed as it is); an indicator with no measured document is at best Attention until the hospital's own assessment */
  measured: boolean;
}

export interface ReadinessIndicatorOut {
  number: number;
  area: string;
  label: string;
  coverage: "OverDelivers" | "Delivers" | "Partly" | "NotYet" | "Outside";
  /** What the software covers (from coverage): complete, partial or none */
  software: "complete" | "partial" | "none";
  /** needed: the surveyor also checks something on site (a display, equipment, a signature, the establishment's own written procedure) */
  on_site_evidence: "needed" | "none";
  note: string;
  /** Ready (green), Attention (amber), NotReady (red), SelfAssess (grey: record the hospital's assessment), NotApplicable */
  state: "Ready" | "Attention" | "NotReady" | "SelfAssess" | "NotApplicable";
  /** Why: the evidence's detail, or the assessment */
  reason: string;
  documents: string[];
  category_i: number[];
  grade: "Red" | "Yellow" | null;
  self_assessment: SelfAssessmentOut | null;
}

export interface SelfAssessmentOut {
  assessment_id: number;
  category: "Clinic" | "IIC" | "IIB" | "IIA" | "I";
  indicator: number;
  status: "Compliant" | "PartlyCompliant" | "NotCompliant" | "NotApplicable";
  score: number | null;
  note: string | null;
  evidence_document_id: number | null;
  evidence_document_title: string | null;
  assessed_by: number;
  assessed_by_name: string;
  assessed_at: string;
}

/** One indicator of a framework. The label is a short reminder in Haspataal's words; the PHC's wording and scoring are in its manual. */
export interface IndicatorOut {
  number: number;
  /** The chapter: AAC or ACC, COP, MOM, PRE, IPC, HIC or IC, CQI or QA, ROM, FMS, HRM, IMS */
  area: string;
  area_name: string;
  /** The standard it belongs to (clinic and Category II manuals), e.g. IMS-1 */
  standard: string | null;
  label: string;
  /** How Haspataal covers it, in the vendor's own assessment: OverDelivers, Delivers, Partly (the software part is incomplete), NotYet, Outside (on site only) */
  coverage: "OverDelivers" | "Delivers" | "Partly" | "NotYet" | "Outside";
  /** What the software covers (from coverage): complete, partial or none */
  software: "complete" | "partial" | "none";
  /** needed: the surveyor also checks something on site (a display, equipment, a signature, the establishment's own written procedure) */
  on_site_evidence: "needed" | "none";
  /** The coverage is the vendor's self-assessment; no PHC surveyor has validated it */
  rating_basis: "self-assessment";
  /** How Haspataal covers it, in one or two sentences */
  note: string;
  /** The inspection documents that evidence it (GET /msds/inspection-pack keys) */
  documents: string[];
  /** The Category I indicators it corresponds to (a clinic indicator: on the same subject, linking evidence and interview preparation, never grades) */
  category_i: number[];
  /** Category I: the colour of the indicator's banner in the PHC's manual, red = Mandatory compliance, yellow = Operational / process compliance; null for the other manuals */
  phc_type: "Mandatory" | "Operational" | null;
  /** Red: full compliance (a score of 10); Yellow: at least 80 % (8). From the manual's scoring matrices (every framework); null only for a framework whose matrices have not been read */
  grade: "Red" | "Yellow" | null;
  /** The service it concerns where the manual says 'if provided' (a capability of GET /establishment); a person still decides NotApplicable */
  applies_if: string | null;
  /** The outcomes the indicator's scoring names (every framework): without PartiallyMet a self-assessment scores 0 or 10 only. Null where the manual prints no Scoring for it (Category I 63): no restriction */
  outcomes: ("FullyMet" | "PartiallyMet" | "NotMet")[] | null;
  /** Verified scoring paragraphs from the framework's manual; null where the manual prints none (Category I 63) */
  scoring_criteria: string[] | null;
  /** Percentages named in those paragraphs, in source order. Read with scoring_criteria: a percentage alone is not a rule */
  percent_thresholds: string[] | null;
  /** The sample the surveyor takes, in the manual's words (e.g. 'sample of at least 10 medical records'); null when the scoring names none */
  sample: string | null;
  /** The one-based PDF page of its survey process in the manual */
  survey_page: number | null;
}

export interface SelfAssessmentIn {
  /** The framework: Clinic (47 indicators), IIC (118), IIB (122), IIA (152), I (162) */
  category: "Clinic" | "IIC" | "IIB" | "IIA" | "I";
  /** The indicator's number in that framework's manual */
  indicator: number;
  status: "Compliant" | "PartlyCompliant" | "NotCompliant" | "NotApplicable";
  /** The manuals' 0-10 scoring scale (a red indicator needs 10, a yellow one 8 in the clinic and Category II manuals); leave it out when not scored: no score is not zero */
  score?: number | null;
  /** Required unless Compliant: what is missing, or why it does not apply */
  note?: string | null;
  /** A scan kept in the compliance register (a photo of the sign board, the fire certificate) */
  evidence_document_id?: number | null;
}

/** The establishment's PHC category as recorded, and what the beds suggest today. */
export interface MsdsProfileOut {
  /** Null until a person records it */
  category: "Clinic" | "IIC" | "IIB" | "IIA" | "I" | null;
  category_label: string | null;
  /** The PHC registration or licence number on every printout */
  registration_number: string | null;
  licence_document: LicenceDocumentOut | null;
  /** The date the category took effect on the licence */
  effective_from: string | null;
  confirmed_at: string | null;
  confirmed_by_name: string | null;
  /** Why the confirmed category differs from the suggestion, when it does */
  reason: string | null;
  /** The beds counted when it was confirmed */
  bed_count: number | null;
  /** The beds the licence names, as entered with the profile; null when none was entered */
  licensed_beds: number | null;
  /** What to look at again: more beds set up than the licence names, a licence outside its category's band. Advice only: the category stays as recorded */
  review: string[];
  suggestion: CategorySuggestionOut;
  /** True when nothing is recorded, or the beds now suggest another band than when it was recorded: offer the admin the facility settings */
  needs_confirmation: boolean;
  /** The PHC frameworks Haspataal holds: Clinic, II C, II B, II A, I */
  standards: StandardOut[];
}

/** The PHC licence in the compliance register, or the entry that renewed it since. */
export interface LicenceDocumentOut {
  document_id: number;
  title: string;
  authority: string | null;
  reference_no: string | null;
  valid_until: string | null;
  state: "Valid" | "DueForRenewal" | "Expired" | "NoExpiry" | "Renewed" | "Withdrawn";
  has_scan: boolean;
}

/** What the beds suggest by the PHC's bands; a person records the category on the licence (POST /establishment/changes with a profile). */
export interface CategorySuggestionOut {
  /** Null: no inpatient bed is set up (a clinic, or a hospital whose beds are not set up yet) */
  category: "I" | "IIA" | "IIB" | "IIC" | null;
  category_label: string | null;
  /** The beds set up: the active beds of the active wards, emergency wards left out */
  beds: number;
  /** The beds in use: those set up, less the ones out of service */
  operational: number;
  /** The beds set up but out of service now (a temporary closure) */
  out_of_service: number;
  /** Whether Haspataal holds the suggested category's framework (all five since 2026-10-14) */
  supported: boolean;
  /** One sentence to show next to the suggestion */
  note: string;
  wards: CountedWardOut[];
}

export interface CountedWardOut {
  ward_id: number;
  code: string;
  name: string;
  ward_type: "General" | "Private" | "SemiPrivate" | "ICU" | "CCU" | "NICU" | "Surgical" | "Pediatric" | "Maternity" | "Emergency" | "Isolation" | "Other";
  /** Its active beds */
  beds: number;
  /** Of those, the beds out of service now (a temporary closure) */
  out_of_service: number;
  /** False for emergency wards: ER observation beds are not indoor strength */
  counted: boolean;
}

export interface StandardOut {
  category: "Clinic" | "IIC" | "IIB" | "IIA" | "I";
  label: string;
  /** The PHC document the indicators come from */
  edition: string;
  indicators: number;
}

export interface ComplianceDocumentOut {
  document_id: number;
  kind: "Licence" | "Registration" | "Certificate" | "Plan" | "Law";
  category: "Hospital" | "Radiation" | "Building" | "Fire" | "Lift" | "Boiler" | "Power" | "BloodTransfusion" | "Food" | "Waste" | "Pharmacy" | "Laboratory" | "Water" | "Environment" | "Emergency" | "Equipment" | "Staff" | "Other";
  title: string;
  authority: string | null;
  reference_no: string | null;
  issued_on: string | null;
  valid_until: string | null;
  renewal_lead_days: number;
  /** The official who keeps it current (MSDS ROM 119 i) */
  responsible_user_id: number | null;
  responsible_name: string | null;
  asset_id: number | null;
  asset_tag: string | null;
  asset_name: string | null;
  department_id: number | null;
  department_name: string | null;
  renewal_applied_on: string | null;
  renewal_reference: string | null;
  has_scan: boolean;
  content_type: "application/pdf" | "image/jpeg" | "image/png" | null;
  size_bytes: number | null;
  note: string | null;
  status: "Current" | "Renewed" | "Withdrawn";
  replaces_id: number | null;
  renewed_by_id: number | null;
  withdrawn_reason: string | null;
  /** Null: shipped with Haspataal */
  created_by_name: string | null;
  created_at: string;
  row_version: number;
  /** Days to the expiry (negative: expired); null without one */
  days_left: number | null;
  /** Computed from the dates every day: DueForRenewal within renewal_lead_days of the expiry */
  state: "Valid" | "DueForRenewal" | "Expired" | "NoExpiry" | "Renewed" | "Withdrawn";
}

/** Readiness for an inspection — GET /api/v1/msds/readiness (who may call: holders of msds.view). */
export function getReadiness(query?: { category?: "Clinic" | "IIC" | "IIB" | "IIA" | "I" | null; date_from?: string | null; date_to?: string | null }): Promise<ReadinessOut> {
  return api<ReadinessOut>("GET", withQuery(`/msds/readiness`, query), undefined);
}

/** The MSDS indicators of a category — GET /api/v1/msds/indicators (who may call: holders of msds.view or msds.inspect). */
export function listIndicators(query?: { category?: "Clinic" | "IIC" | "IIB" | "IIA" | "I" | null; area?: string | null }): Promise<IndicatorOut[]> {
  return api<IndicatorOut[]>("GET", withQuery(`/msds/indicators`, query), undefined);
}

/** The hospital's assessments (history, newest first) — GET /api/v1/msds/self-assessments (who may call: holders of msds.view). */
export function listAssessments(query: { category: "Clinic" | "IIC" | "IIB" | "IIA" | "I"; indicator?: number | null; limit?: number }): Promise<SelfAssessmentOut[]> {
  return api<SelfAssessmentOut[]>("GET", withQuery(`/msds/self-assessments`, query), undefined);
}

/** Record the hospital's own assessment of an indicator — POST /api/v1/msds/self-assessments (who may call: holders of msds.assess). */
export function assessMsdsSelfAssessments(body: SelfAssessmentIn): Promise<SelfAssessmentOut> {
  return api<SelfAssessmentOut>("POST", `/msds/self-assessments`, body, { idempotent: true });
}

/** The PHC category: as confirmed, and what the beds suggest — GET /api/v1/msds/profile (who may call: holders of msds.view or establishment.manage or msds.inspect). */
export function getProfile(): Promise<MsdsProfileOut> {
  return api<MsdsProfileOut>("GET", `/msds/profile`, undefined);
}

/** The compliance register — GET /api/v1/facility/compliance-documents (who may call: holders of facility.view or facility.compliance.manage or blood.bank.manage). */
export function listDocumentsFacilityCompliance(query?: { kind?: "Licence" | "Registration" | "Certificate" | "Plan" | "Law" | null; category?: "Hospital" | "Radiation" | "Building" | "Fire" | "Lift" | "Boiler" | "Power" | "BloodTransfusion" | "Food" | "Waste" | "Pharmacy" | "Laboratory" | "Water" | "Environment" | "Emergency" | "Equipment" | "Staff" | "Other" | null; state?: "Valid" | "DueForRenewal" | "Expired" | "NoExpiry" | null; responsible_user_id?: number | null; include_closed?: boolean }): Promise<ComplianceDocumentOut[]> {
  return api<ComplianceDocumentOut[]>("GET", withQuery(`/facility/compliance-documents`, query), undefined);
}
